# The NotEnoughInformationError persists, which suggests that one or more of the lists (affordable_cars, car_reviews, car_addresses, car_types, affordable_car_prices) may be empty or missing information.
# Let's check if there are any affordable car rental companies and if not, inform the user accordingly.
# If there are, but some have missing reviews, filter those out and only pass companies with all required info.

if len(affordable_cars) == 0:
    print("Sorry, there are no car rental companies in Paris with prices under 50 euros per day.")
else:
    # Filter out companies with missing reviews or missing prices
    cars_with_reviews_and_prices = [
        name for name in affordable_cars
        if name in car_reviews and name in affordable_car_prices
    ]
    if len(cars_with_reviews_and_prices) == 0:
        print("Sorry, there are no affordable car rental companies in Paris with available reviews and prices.")
    else:
        # Prepare the filtered data
        filtered_car_reviews = {name: car_reviews[name] for name in cars_with_reviews_and_prices}
        filtered_car_prices = {name: affordable_car_prices[name] for name in cars_with_reviews_and_prices}
        filtered_car_addresses = {name: car_addresses[name] for name in cars_with_reviews_and_prices if name in car_addresses}
        filtered_car_types = {name: car_types[name] for name in cars_with_reviews_and_prices if name in car_types}

        best_car_rental_result = query_ai_assistant(
            f"""Given the following information about car rental companies in Paris:
Names: {cars_with_reviews_and_prices}
